    position: 'absolute',
    margin: '0px',
    boxSizing: 'border-box',
    width: `${node.offsetWidth}px`,
    height: `${node.offsetHeight}px`,
    pointerEvents: 'none',
    translate: 'none',
    transform: 'none',
    opacity: '',
