'use client';

import * as React from 'react';
import { PresenceContext, type Transition } from 'motion/react';

import {
  motionTokens,
  useCheckAnimation,
  useShouldReduceMotion,
  useTempoTransition,
  type CheckAnimation,
} from '../utils/motion';
import {
  IndicatorContent,
  mergeRefs,
  type IndicatorContentProps,
  type IndicatorHandle,
} from './controls/indicator';
import { glideFrom, stopGlide } from './glide';

const DRAW_TRANSITION: Transition = {
  ...motionTokens.transition.check,
  delay: 0,
};
const ERASE_TRANSITION: Transition = motionTokens.transition.uncheck;
const POP_TRANSITION: Transition = motionTokens.spring.checkPop;
const UNPOP_TRANSITION: Transition = motionTokens.transition.popOut;

const GLIDE_TRANSITION = motionTokens.spring.highlight;

const PICK_HOLD: Record<CheckAnimation, number> = { draw: 0.25, pop: 0.15 };

type Picked = CheckAnimation | false;

function usePickHold() {
  const { delay: draw = 0 } = useTempoTransition({ delay: PICK_HOLD.draw });
  const { delay: pop = 0 } = useTempoTransition({ delay: PICK_HOLD.pop });
  return (look: CheckAnimation) => (look === 'draw' ? draw : pop);
}

type ItemCheckAnimationProps = {
  animation?: CheckAnimation;
  transition?: Transition;
};

type GroupReport = {
  handle: IndicatorHandle;
  shown: boolean;
  reduce: boolean;
  glide: Transition;
  rect?: DOMRect;
};

type CheckGroup = { report: (report: GroupReport) => void };

function createCheckGroup(): CheckGroup {
  let pending: GroupReport[] = [];
  const settle = () => {
    const reports = pending;
    pending = [];
    const last = new Map(reports.map((r) => [r.handle.element, r]));
    const shown = [...last.values()].filter((r) => r.shown);
    const hidden = [...last.values()].filter((r) => !r.shown);
    const to = shown.length === 1 ? shown[0]! : null;
    const from =
      to && !to.reduce ? hidden.find((r) => r.handle.isShown()) : undefined;
    if (to && from) {
      const start = from.rect ?? from.handle.element.getBoundingClientRect();
      for (const r of hidden) {
        stopGlide(r.handle.element);
        r.handle.toggle(false, false);
      }
      to.handle.toggle(true, false);
      glideFrom(to.handle.element, start, to.glide);
      return;
    }
    for (const r of hidden) r.handle.toggle(false, true);
    for (const r of shown) r.handle.toggle(true, true);
  };
  return {
    report: (report) => {
      if (pending.length === 0) queueMicrotask(settle);
      pending.push(report);
    },
  };
}

function useCheckGroup(): CheckGroup {
  const [group] = React.useState(createCheckGroup);
  return group;
}

type RegisterCheck = (element: Element, look: CheckAnimation) => () => void;

const CheckRegistryContext = React.createContext<RegisterCheck | null>(null);

function useCheckRegistry() {
  const checksRef = React.useRef(new Map<Element, CheckAnimation>());
  const registerCheck = React.useCallback<RegisterCheck>((element, look) => {
    checksRef.current.set(element, look);
    return () => {
      checksRef.current.delete(element);
    };
  }, []);
  const checkOf = React.useCallback((item?: Element | null): Picked => {
    let found: Picked = false;
    for (const [check, look] of checksRef.current) {
      if (item && !item.contains(check)) continue;
      if (look === 'draw') return 'draw';
      found = look;
    }
    return found;
  }, []);
  const hasCheck = React.useCallback(
    (item?: Element | null) => checkOf(item) !== false,
    [checkOf],
  );
  return { registerCheck, hasCheck, checkOf };
}

type ItemCheckProps = Omit<
  IndicatorContentProps,
  'kind' | 'animation' | 'transition' | 'exitTransition' | 'coordinate'
> &
  ItemCheckAnimationProps & {
    multiple: boolean;
    group: CheckGroup | null;
  };

const settledLists = new WeakSet<Element>();

function inSettledList(check: Element | null) {
  const list = check?.closest('[role="menu"], [role="listbox"]');
  if (!list) return true;
  if (settledLists.has(list)) return true;
  requestAnimationFrame(() => settledLists.add(list));
  return false;
}

function ItemCheck({
  multiple,
  group,
  animation,
  transition,
  ref,
  ...props
}: ItemCheckProps) {
  const look = useCheckAnimation(animation);
  const reduce = useShouldReduceMotion();
  const glide = useTempoTransition(transition ?? GLIDE_TRANSITION);
  const gliding = look === 'pop' && !multiple && group !== null;
  const register = React.use(CheckRegistryContext);
  const elementRef = React.useRef<HTMLElement>(null);
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    return element && register ? register(element, look) : undefined;
  }, [register, look]);
  const mergedRef = React.useMemo(
    () =>
      mergeRefs<HTMLElement>(
        ref as React.Ref<HTMLElement> | undefined,
        elementRef,
        gliding ? asTransformable : undefined,
      ),
    [ref, gliding],
  );
  const coordinate = React.useCallback(
    (handle: IndicatorHandle, shown: boolean) =>
      group?.report({ handle, shown, reduce, glide }),
    [group, reduce, glide],
  );
  const latestRef = React.useRef({ checked: props.checked, reduce, glide });
  React.useLayoutEffect(() => {
    latestRef.current = { checked: props.checked, reduce, glide };
  });
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!gliding || !group || !element) return undefined;
    return () => {
      const { checked, ...latest } = latestRef.current;
      if (!checked || !element.isConnected) return;
      group.report({
        handle: { element, toggle: () => {}, isShown: () => true },
        shown: false,
        rect: element.getBoundingClientRect(),
        ...latest,
      });
    };
  }, [gliding, group]);
  const [enter, exit] =
    look === 'pop'
      ? [POP_TRANSITION, UNPOP_TRANSITION]
      : [DRAW_TRANSITION, ERASE_TRANSITION];

  return (
    <PresenceContext value={null}>
      <IndicatorContent
        {...props}
        ref={mergedRef}
        kind="check"
        animation={look}
        transition={transition ?? enter}
        exitTransition={transition ?? exit}
        coordinate={gliding ? coordinate : undefined}
        animateOnMount={() => inSettledList(elementRef.current)}
      />
    </PresenceContext>
  );
}

function asTransformable(node: HTMLElement | null) {
  if (!node || getComputedStyle(node).display !== 'inline') return;
  const alone = node.parentElement?.childNodes.length === 1;
  node.style.setProperty('display', alone ? 'block' : 'inline-block');
}

type Picks = {
  markPick: (look: CheckAnimation) => void;
  hasCheck: (item?: Element | null) => boolean;
  checkOf: (item?: Element | null) => Picked;
};

const PickContext = React.createContext<Picks | null>(null);

function usePicks() {
  const { registerCheck, hasCheck, checkOf } = useCheckRegistry();
  const pickingRef = React.useRef<Picked>(false);
  const markPick = React.useCallback((look: CheckAnimation) => {
    if (pickingRef.current !== 'draw') pickingRef.current = look;
    setTimeout(() => {
      pickingRef.current = false;
    });
  }, []);
  const wasPicked = React.useCallback(() => pickingRef.current, []);
  const picks = React.useMemo(
    () => ({ markPick, hasCheck, checkOf }),
    [markPick, hasCheck, checkOf],
  );
  return { picks, registerCheck, wasPicked };
}

export {
  GLIDE_TRANSITION,
  PICK_HOLD,
  CheckRegistryContext,
  usePickHold,
  ItemCheck,
  PickContext,
  useCheckGroup,
  useCheckRegistry,
  usePicks,
  type CheckGroup,
  type ItemCheckAnimationProps,
  type ItemCheckProps,
  type Picked,
  type RegisterCheck,
};

'use client';

import * as React from 'react';
import type { Transition } from 'motion/react';

import { motionTokens, toCssTiming, useTempoTransition } from '../utils/motion';
import { carries, curveFrom, velocityOf, type Run } from './momentum';

class HandoffEntry {
  node: HTMLElement | null = null;
  open = false;
  openedAt = 0;
  movedOn = false;
  dropped = false;
  pending: HandoffEntry | null = null;
  readonly nested = new Set<HTMLElement>();
  private onDrop = () => {};

  attach(node: HTMLElement | null, onDrop: () => void) {
    this.node = node;
    this.onDrop = onDrop;
  }

  drop() {
    this.dropped = true;
    this.pending = null;
    for (const node of [this.node, ...this.nested]) hide(node);
    this.onDrop();
  }

  reopen() {
    if (!this.dropped) return;
    this.dropped = false;
    show(this.node);
  }

  await(source: HandoffEntry | null) {
    this.pending = source;
  }

  addNested(node: HTMLElement) {
    show(node);
    this.nested.add(node);
    return () => {
      this.nested.delete(node);
    };
  }
}

const hidden = new WeakSet<HTMLElement>();

function hide(node: HTMLElement | null) {
  if (!node) return;
  node.style.visibility = 'hidden';
  hidden.add(node);
}

function show(node: HTMLElement | null) {
  if (!node || !hidden.has(node)) return;
  node.style.visibility = '';
  hidden.delete(node);
}

class HandoffGroup {
  private entries = new Set<HandoffEntry>();
  private clock = 0;

  add(entry: HandoffEntry) {
    this.entries.add(entry);
    return () => {
      this.entries.delete(entry);
    };
  }

  setOpen(entry: HandoffEntry, open: boolean, movedOn: boolean) {
    entry.open = open;
    entry.movedOn = !open && movedOn;
    if (open) entry.openedAt = this.clock += 1;
  }

  source(self: HandoffEntry) {
    let source: HandoffEntry | null = null;
    for (const entry of this.entries) {
      if (entry === self || entry.dropped) continue;
      if (!entry.open && !(entry.movedOn && isShown(entry.node))) continue;
      if (!entry.node?.isConnected) continue;
      if (!source || entry.openedAt > source.openedAt) source = entry;
    }
    const skipped: HandoffEntry[] = [];
    while (
      source?.pending &&
      !source.pending.dropped &&
      source.pending.node?.isConnected
    ) {
      skipped.push(source);
      source = source.pending;
    }
    return source ? { entry: source, skipped } : null;
  }
}

function isShown(node: HTMLElement | null) {
  if (!node?.isConnected) return false;
  const style = getComputedStyle(node);
  return style.visibility !== 'hidden' && Number(style.opacity) > 0.02;
}

function canAnimate() {
  return (
    typeof Element !== 'undefined' &&
    typeof Element.prototype.animate === 'function' &&
    typeof Element.prototype.getAnimations === 'function'
  );
}

const MenuHandoffContext = React.createContext<HandoffGroup | null>(null);

const HandoffNestedContext = React.createContext<HandoffEntry | null>(null);

function useHandoffGroup(): HandoffGroup {
  const [group] = React.useState(() => new HandoffGroup());
  return group;
}

function useHandoffNested(
  nodeRef: React.RefObject<HTMLElement | null>,
  nested: boolean,
) {
  const parent = React.use(HandoffNestedContext);
  React.useLayoutEffect(() => {
    const node = nodeRef.current;
    if (!nested || !parent || !node) return;
    return parent.addNested(node);
  }, [nested, parent, nodeRef]);
}

type Opening = {
  open: boolean;
  source: HandoffEntry | null;
  skipped: HandoffEntry[];
  opacity: number;
};

const UNIQUE_ATTRIBUTES = [
  'id',
  'data-testid',
  'tabindex',
  'autofocus',
  'data-radix-collection-item',
];

const ANIMATED_PROPERTIES = [
  'opacity',
  'transform',
  'translate',
  'scale',
  'rotate',
  'filter',
  'clip-path',
] as const;

const SKIP = 'data-animate-ui-handoff-skip';

const LAYER = 'data-animate-ui-handoff';

type Layer = {
  menu: string | null;
  to: [number, number];
  fade: Animation | null;
};

const layers = new WeakMap<HTMLElement, Layer>();

const menuOf = (popover: HTMLElement) =>
  popover.id || popover.getAttribute('aria-labelledby') || null;

function translationOf(style: CSSStyleDeclaration): [number, number] {
  const match = style.transform.match(/^matrix\(([^)]+)\)$/);
  if (!match) return [0, 0];
  const values = match[1]!.split(',').map(Number);
  return [values[4] ?? 0, values[5] ?? 0];
}

type ContentCopy = {
  element: HTMLElement;
  menu: string | null;
  left: number;
  top: number;
  scrolls: [Element, number, number][];
};

function freeze(
  original: Element,
  copy: Element,
  scrolls: ContentCopy['scrolls'],
) {
  const style = (copy as Partial<ElementCSSInlineStyle>).style;
  if (style && original.getAnimations().length > 0) {
    const computed = getComputedStyle(original);
    for (const property of ANIMATED_PROPERTIES)
      style.setProperty(property, computed.getPropertyValue(property));
  }
  if (original.scrollTop || original.scrollLeft)
    scrolls.push([copy, original.scrollTop, original.scrollLeft]);
  for (let i = 0; i < original.children.length; i++) {
    const child = copy.children[i];
    if (child) freeze(original.children[i]!, child, scrolls);
  }
}

function copyContent(popover: HTMLElement, nested: Set<HTMLElement>) {
  const computed = getComputedStyle(popover);
  const element = popover.ownerDocument.createElement('div');
  element.setAttribute('aria-hidden', 'true');
  element.setAttribute('inert', '');
  element.setAttribute(LAYER, '');
  Object.assign(element.style, {
    position: 'absolute',
    margin: '0px',
    boxSizing: 'border-box',
    width: `${popover.clientWidth}px`,
    height: `${popover.clientHeight}px`,
    overflow: 'hidden',
    pointerEvents: 'none',
    padding: computed.padding,
    display: computed.display === 'inline' ? 'block' : computed.display,
    flexDirection: computed.flexDirection,
    flexWrap: computed.flexWrap,
    alignItems: computed.alignItems,
    justifyContent: computed.justifyContent,
    gap: computed.gap,
    gridTemplateColumns: computed.gridTemplateColumns,
    gridTemplateRows: computed.gridTemplateRows,
  });
  const skipped: Element[] = [];
  for (const node of nested) {
    if (!popover.contains(node)) continue;
    const top = node.closest('[data-radix-popper-content-wrapper]') ?? node;
    if (popover.contains(top) && top !== popover) {
      top.setAttribute(SKIP, '');
      skipped.push(top);
    }
  }
  const scrolls: ContentCopy['scrolls'] = [];
  if (popover.scrollTop || popover.scrollLeft)
    scrolls.push([element, popover.scrollTop, popover.scrollLeft]);
  for (const node of Array.from(popover.childNodes)) {
    if (
      node instanceof Element &&
      (node.hasAttribute(LAYER) || node.hasAttribute(SKIP))
    )
      continue;
    const copy = node.cloneNode(true);
    if (node instanceof Element && copy instanceof Element) {
      freeze(node, copy, scrolls);
      for (const element of [copy, ...copy.querySelectorAll('*')])
        for (const name of UNIQUE_ATTRIBUTES) element.removeAttribute(name);
      for (const element of copy.querySelectorAll(`[${SKIP}]`))
        element.remove();
    }
    element.appendChild(copy);
  }
  for (const node of skipped) node.removeAttribute(SKIP);
  return {
    element,
    menu: menuOf(popover),
    left: popover.clientLeft,
    top: popover.clientTop,
    scrolls,
  } satisfies ContentCopy;
}

type Leaving = {
  element: HTMLElement;
  menu: string | null;
  box: DOMRect;
  opacity: number;
  slide: [number, number];
  to: [number, number];
};

function leavingIn(popover: HTMLElement): Leaving[] {
  const found: Leaving[] = [];
  for (const element of Array.from(popover.children)) {
    if (!(element instanceof HTMLElement) || !element.hasAttribute(LAYER))
      continue;
    const style = getComputedStyle(element);
    const layer = layers.get(element);
    found.push({
      element,
      menu: layer?.menu ?? null,
      box: element.getBoundingClientRect(),
      opacity: Number(style.opacity),
      slide: translationOf(style),
      to: layer?.to ?? [0, 0],
    });
  }
  return found;
}

type HandoffTimings = {
  move: Transition;
  velocity?: number[];
  since?: number | null;
  out: Transition;
  fadeIn: Transition;
  slideIn: Transition;
};

const running = new WeakMap<HTMLElement, Animation[]>();
const moving = new WeakMap<HTMLElement, { run: Run; animation: Animation }>();

function velocityOfPopover(popover: HTMLElement) {
  const move = moving.get(popover);
  const time = move?.animation.currentTime;
  if (!move || typeof time !== 'number') return [0, 0, 0, 0];
  return velocityOf(move.run, time);
}
const positioned = new WeakSet<HTMLElement>();

function release(popover: HTMLElement) {
  if (!positioned.has(popover) || popover.querySelector(`:scope > [${LAYER}]`))
    return;
  positioned.delete(popover);
  popover.style.position = '';
}

function handOver(
  popover: HTMLElement,
  from: DOMRect,
  previous: ContentCopy,
  leaving: Leaving[],
  timings: HandoffTimings,
) {
  for (const animation of running.get(popover) ?? []) animation.cancel();
  for (const copy of popover.querySelectorAll(`:scope > [${LAYER}]`))
    copy.remove();
  const animations: Animation[] = [];
  running.set(popover, animations);
  const animate = (
    element: Element,
    keyframes: Keyframe[],
    options: KeyframeAnimationOptions,
  ) => {
    const animation = element.animate(keyframes, options);
    animations.push(animation);
    return animation;
  };

  const transform = popover.style.transform;
  popover.style.transform = 'none';
  const to = popover.getBoundingClientRect();
  popover.style.transform = transform;
  const computed = getComputedStyle(popover);
  const items = Array.from(popover.children).filter(
    (item) => !item.hasAttribute(LAYER),
  );

  const shift = motionTokens.shift.handoff;
  const x = from.left - to.left;
  const y = from.top - to.top;
  const offset = [x, y, from.width - to.width, from.height - to.height];
  const curve = curveFrom(
    timings.move,
    offset,
    timings.velocity ?? [0, 0, 0, 0],
  );
  const move = { duration: curve.duration, easing: curve.easing };
  const horizontal = Math.abs(x) >= Math.abs(y);
  const way = -Math.sign(horizontal ? x : y);
  const along = (distance: number): [number, number] =>
    horizontal ? [distance, 0] : [0, distance];

  const menu = menuOf(popover);
  const back = menu
    ? leaving.find((layer) => layer.menu === menu && layer.opacity > 0.02)
    : undefined;
  let enter: { slide: [number, number]; shown: number } = {
    slide: along(way * shift),
    shown: 0,
  };
  const first = items[0];
  const theirs = back?.element.firstElementChild;
  if (back && first && theirs) {
    const own = first.getBoundingClientRect();
    const box = theirs.getBoundingClientRect();
    const rest = Number(getComputedStyle(first).opacity) || 1;
    enter = {
      slide: [box.left - own.left, box.top - own.top],
      shown: Math.min(
        1,
        (back.opacity * Number(getComputedStyle(theirs).opacity)) / rest,
      ),
    };
  }

  const marginRight = parseFloat(computed.marginRight) || 0;
  const marginBottom = parseFloat(computed.marginBottom) || 0;
  const sizing = {
    boxSizing: 'border-box',
    minWidth: '0px',
    maxWidth: 'none',
    minHeight: '0px',
    maxHeight: 'none',
  };
  const moved: Animation[] = [];
  const resize = animate(
    popover,
    [
      {
        ...sizing,
        width: `${from.width}px`,
        height: `${from.height}px`,
        marginRight: `${marginRight + to.width - from.width}px`,
        marginBottom: `${marginBottom + to.height - from.height}px`,
      },
      {
        ...sizing,
        width: `${to.width}px`,
        height: `${to.height}px`,
        marginRight: `${marginRight}px`,
        marginBottom: `${marginBottom}px`,
      },
    ],
    move,
  );
  moving.set(popover, { run: { offset, curve }, animation: resize });
  moved.push(resize);
  const moves = Math.abs(x) >= 0.5 || Math.abs(y) >= 0.5;
  if (moves) {
    const translate = animate(
      popover,
      [{ translate: `${x}px ${y}px` }, { translate: '0px 0px' }],
      {
        ...move,
        composite: 'add',
      },
    );
    moved.push(translate);
  }
  const fadeIn = toCssTiming(timings.fadeIn);
  const slideIn = toCssTiming(timings.slideIn);
  const out = toCssTiming(timings.out);
  const clip = { overflow: 'hidden', whiteSpace: 'nowrap' };
  animate(popover, [clip, clip], {
    duration: Math.max(move.duration, out.duration, fadeIn.duration),
  });

  const [slideX, slideY] = enter.slide;
  const slides = Math.abs(slideX) >= 0.5 || Math.abs(slideY) >= 0.5;
  for (const item of items) {
    const rest = getComputedStyle(item).opacity;
    animate(
      item,
      [{ opacity: Number(rest) * enter.shown }, { opacity: rest }],
      fadeIn,
    );
    if (moves)
      moved.push(
        animate(
          item,
          [{ translate: `${-x}px ${-y}px` }, { translate: '0px 0px' }],
          {
            ...move,
            composite: 'add',
          },
        ),
      );
    if (slides)
      animate(
        item,
        [{ translate: `${slideX}px ${slideY}px` }, { translate: '0px 0px' }],
        {
          ...slideIn,
          composite: 'add',
        },
      );
  }

  if (computed.position === 'static' || positioned.has(popover)) {
    positioned.add(popover);
    popover.style.position = 'relative';
  }
  const originLeft = from.left + popover.clientLeft;
  const originTop = from.top + popover.clientTop;
  const leave = (
    element: HTMLElement,
    {
      menu: layerMenu,
      left,
      top,
      opacity,
      slide,
      to: slideTo,
    }: {
      menu: string | null;
      left: number;
      top: number;
      opacity: number;
      slide: [number, number];
      to: [number, number];
    },
  ) => {
    for (const animation of element.getAnimations()) animation.cancel();
    element.style.left = `${left - originLeft}px`;
    element.style.top = `${top - originTop}px`;
    popover.appendChild(element);
    if (moves)
      moved.push(
        element.animate(
          [{ translate: '0px 0px' }, { translate: `${x}px ${y}px` }],
          { ...move, composite: 'add', fill: 'forwards' },
        ),
      );
    if (slide[0] !== slideTo[0] || slide[1] !== slideTo[1])
      element.animate(
        [
          { transform: `translate(${slide[0]}px, ${slide[1]}px)` },
          { transform: `translate(${slideTo[0]}px, ${slideTo[1]}px)` },
        ],
        { ...out, composite: 'add', fill: 'forwards' },
      );
    const fade = element.animate([{ opacity }, { opacity: 0 }], {
      ...out,
      fill: 'forwards',
    });
    const layer: Layer = { menu: layerMenu, to: slideTo, fade };
    layers.set(element, layer);
    const remove = () => {
      if (layers.get(element)?.fade !== fade) return;
      element.remove();
      release(popover);
    };
    fade.finished.then(remove, remove);
  };

  for (const layer of leaving) {
    if (layer === back) {
      layers.delete(layer.element);
      layer.element.remove();
      continue;
    }
    if (layer.opacity <= 0.02) continue;
    leave(layer.element, {
      menu: layer.menu,
      left: layer.box.left - layer.slide[0],
      top: layer.box.top - layer.slide[1],
      opacity: layer.opacity,
      slide: layer.slide,
      to: layer.to,
    });
  }

  const copy = previous.element;
  leave(copy, {
    menu: previous.menu,
    left: from.left + previous.left,
    top: from.top + previous.top,
    opacity: 1,
    slide: [0, 0],
    to: along(-way * shift),
  });
  for (const [element, top, left] of previous.scrolls) {
    element.scrollTop = top;
    element.scrollLeft = left;
  }

  const timeline = popover.ownerDocument.timeline;
  const now = timeline.currentTime;
  if (
    carries(curve, offset) &&
    typeof now === 'number' &&
    typeof timings.since === 'number'
  ) {
    const since = Math.max(timings.since, now - move.duration);
    for (const animation of moved) animation.startTime = since;
    return;
  }
  for (const animation of moved) animation.pause();
  requestAnimationFrame(() => {
    const start = timeline.currentTime;
    for (const animation of moved)
      if (animation.playState === 'paused') animation.startTime = start;
  });
}

type HandoffOptions = {
  nodeRef: React.RefObject<HTMLElement | null>;
  open: boolean;
  movedOn?: boolean;
  transition: Transition;
  reduce: boolean;
  onDrop?: () => void;
};

type Handoff = {
  from: { opacity: number } | null;
  dropped: boolean;
  entry: HandoffEntry;
};

function isInstant(transition: Transition) {
  return toCssTiming(transition).duration === 0;
}

function useMenuHandoff(
  group: HandoffGroup | null,
  {
    nodeRef,
    open,
    movedOn = false,
    transition,
    reduce,
    onDrop,
  }: HandoffOptions,
): Handoff {
  const [entry] = React.useState(() => new HandoffEntry());
  const enabled = group !== null && !reduce && canAnimate();
  const take = (): Opening => {
    const found = open && enabled ? group.source(entry) : null;
    return {
      open,
      source: found?.entry ?? null,
      skipped: found?.skipped ?? [],
      opacity: found?.entry.node
        ? Number(getComputedStyle(found.entry.node).opacity)
        : 1,
    };
  };
  const [opening, setOpening] = React.useState(take);
  const [dropped, setDropped] = React.useState(false);
  if (opening.open !== open) {
    setOpening(take());
    if (open) setDropped(false);
  }

  const out = useTempoTransition(motionTokens.transition.handoffOut);
  const fadeIn = useTempoTransition(motionTokens.transition.handoffIn);
  const slideIn = useTempoTransition(motionTokens.spring.handoff);
  const timingsRef = React.useRef<HandoffTimings>({
    move: transition,
    out,
    fadeIn,
    slideIn,
  });
  const onDropRef = React.useRef(onDrop);
  React.useLayoutEffect(() => {
    timingsRef.current = { move: transition, out, fadeIn, slideIn };
    onDropRef.current = onDrop;
    entry.attach(nodeRef.current, () => {
      setDropped(true);
      onDropRef.current?.();
    });
  });

  React.useLayoutEffect(() => group?.add(entry), [group, entry]);

  React.useEffect(() => {
    group?.setOpen(entry, open, movedOn);
  }, [entry, group, open, movedOn]);

  React.useLayoutEffect(() => {
    const node = nodeRef.current;
    if (!opening.open || !node) return;
    entry.reopen();
    const source = opening.source;
    if (!source?.node) return;
    entry.await(source);
    const skipped = opening.skipped;
    const from = source.node.getBoundingClientRect();
    const velocity = velocityOfPopover(source.node);
    const since = source.node.ownerDocument.timeline.currentTime;
    const instant = isInstant(timingsRef.current.move);
    const previous = instant ? null : copyContent(source.node, source.nested);
    let swapped = false;
    const swap = () => {
      if (swapped) return;
      swapped = true;
      stop();
      entry.await(null);
      const leaving = previous && source.node ? leavingIn(source.node) : [];
      for (const other of skipped) other.drop();
      source.drop();
      if (node.isConnected && previous)
        handOver(node, from, previous, leaving, {
          ...timingsRef.current,
          velocity,
          since: typeof since === 'number' ? since : null,
        });
      if (source.node) release(source.node);
    };
    const observer =
      typeof ResizeObserver === 'function' ? new ResizeObserver(swap) : null;
    observer?.observe(node);
    const frame = requestAnimationFrame(swap);
    const stop = () => {
      observer?.disconnect();
      cancelAnimationFrame(frame);
    };
    return stop;
  }, [opening, entry, nodeRef]);

  return {
    from: opening.source ? { opacity: opening.opacity } : null,
    dropped,
    entry,
  };
}

function takeOver(
  from: { opacity: number },
  transition: Transition,
): { opacity: number[]; scale: number; transition: Transition } {
  return {
    opacity: [from.opacity, 1],
    scale: 1,
    transition: { ...transition, scale: { duration: 0 } },
  };
}

export {
  HandoffNestedContext,
  MenuHandoffContext,
  takeOver,
  useHandoffGroup,
  useHandoffNested,
  useMenuHandoff,
  freeze,
  release,
  translationOf,
  layers,
  positioned,
  LAYER,
  UNIQUE_ATTRIBUTES,
  type Layer,
  type HandoffTimings,
  type HandoffGroup,
};

import * as React from 'react';
import {
  motion,
  type TargetAndTransition,
  type Transition,
} from 'motion/react';

import { motionTokens, toCssTiming, useTempoTransition } from '../utils/motion';

export const OVERLAY_TRANSITION = motionTokens.transition.overlay;

export const DIALOG_TRANSITION = motionTokens.spring.dialog;

export const DISMISS_TRANSITION = motionTokens.transition.dismiss;

export const DRAWER_EXIT_TRANSITION = motionTokens.transition.drawerOut;

const CONTENT_FADE = motionTokens.transition.dialogFade;

export const TOAST_TRANSITION = motionTokens.spring.toast;

export const DRAWER_TRANSITION = motionTokens.transition.drawer;

export const SHEET_TRANSITION = motionTokens.transition.sheet;

export type ContentFlipProps = {
  from?: FlipDirection;
};

export type ModalAnimationProps = {
  transition?: Transition;
  exitTransition?: Transition;
};

export function useModalTransitions(
  transition: Transition | undefined,
  exitTransition: Transition | undefined,
  fallback: Transition,
  exitFallback?: Transition,
): { enter: Transition; exit: Transition } {
  const enter = useTempoTransition(transition ?? fallback);
  const exit = useTempoTransition(
    exitTransition ?? exitFallback ?? transition ?? fallback,
  );
  return { enter, exit };
}

export function useOverlayTransitions(
  transition: Transition | undefined,
  exitTransition: Transition | undefined,
) {
  return useModalTransitions(transition, exitTransition, OVERLAY_TRANSITION);
}

export type ModalSide = 'top' | 'right' | 'bottom' | 'left';

export function useContentTransitions(
  side: ModalSide | undefined,
  transition: Transition | undefined,
  exitTransition: Transition | undefined,
): { enter: Transition; exit: Transition } {
  const { enter, exit } = useModalTransitions(
    transition,
    exitTransition,
    side ? SHEET_TRANSITION : DIALOG_TRANSITION,
    DISMISS_TRANSITION,
  );
  const fade = useTempoTransition(CONTENT_FADE);
  return {
    enter: side || transition ? enter : { ...enter, opacity: fade },
    exit,
  };
}

const SIDES: readonly string[] = ['top', 'right', 'bottom', 'left'];

export function getModalSide(value: unknown): ModalSide | undefined {
  return typeof value === 'string' && SIDES.includes(value)
    ? (value as ModalSide)
    : undefined;
}

const OFFSCREEN: Record<ModalSide, string> = {
  top: 'translateY(-100%)',
  right: 'translateX(100%)',
  bottom: 'translateY(100%)',
  left: 'translateX(-100%)',
};

export type FlipDirection = 'top' | 'bottom' | 'left' | 'right';

function getFlip(from: FlipDirection) {
  const axis = from === 'top' || from === 'bottom' ? 'rotateX' : 'rotateY';
  const angle = from === 'bottom' || from === 'left' ? '20deg' : '-20deg';
  return {
    tipped: `perspective(500px) ${axis}(${angle}) scale(${motionTokens.scale.dialog})`,
    upright: `perspective(500px) ${axis}(0deg) scale(1)`,
  };
}

export type ModalTargets = {
  initial: TargetAndTransition;
  animate: TargetAndTransition;
  exit: TargetAndTransition;
};

type TargetOptions = {
  enter: Transition;
  exit: Transition;
};

export function getContentTargets({
  side,
  from = 'top',
  reduce,
  enter,
  exit,
}: TargetOptions & {
  side: ModalSide | undefined;
  from?: FlipDirection;
  reduce: boolean;
}): ModalTargets {
  if (side) {
    const shown =
      side === 'left' || side === 'right' ? 'translateX(0%)' : 'translateY(0%)';
    const hidden = {
      opacity: 0,
      transform: reduce ? shown : OFFSCREEN[side],
    };
    return {
      initial: hidden,
      animate: { opacity: 1, transform: shown, transition: enter },
      exit: { ...hidden, transition: exit },
    };
  }

  const { tipped, upright } = getFlip(from);
  const hidden = {
    opacity: 0,
    filter: motionTokens.blur.surface,
    transform: reduce ? upright : tipped,
  };
  return {
    initial: hidden,
    animate: {
      opacity: 1,
      filter: 'blur(0px)',
      transform: upright,
      transition: enter,
    },
    exit: { ...hidden, transition: exit },
  };
}

export function useEnterAfterPaint() {
  const [ready, setReady] = React.useState(false);
  React.useLayoutEffect(() => {
    const id = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(id);
  }, []);
  return ready;
}

export function getAnimateTarget(
  targets: ModalTargets,
  open: boolean,
  keepMounted: boolean,
): TargetAndTransition {
  return keepMounted && !open ? targets.exit : targets.animate;
}

export function useHiddenWhenClosed(open: boolean, keepMounted: boolean) {
  const [settled, setSettled] = React.useState(!open);
  if (open && settled) setSettled(false);

  return {
    hidden: keepMounted && !open && settled,
    onAnimationComplete: () => {
      if (!open) setSettled(true);
    },
  };
}

type BackdropValues = Record<
  'backgroundColor' | 'backdropFilter' | 'opacity',
  string
>;

const CLEAR: BackdropValues = {
  backgroundColor: 'transparent',
  backdropFilter: 'none',
  opacity: '0',
};

type Backdrop = BackdropValues & {
  hasImage: boolean;
};

function readBackdrop(element: HTMLElement): Backdrop {
  const style = getComputedStyle(element);
  return {
    backgroundColor: style.backgroundColor,
    backdropFilter: style.backdropFilter,
    opacity: style.opacity,
    hasImage: style.backgroundImage !== 'none',
  };
}

function backdropKeyframes(
  rest: Backdrop,
  start: BackdropValues,
  end: BackdropValues,
): Keyframe[] {
  const frame = (values: BackdropValues) => ({
    backgroundColor: values.backgroundColor,
    backdropFilter: values.backdropFilter,
    ...(rest.hasImage ? { opacity: values.opacity } : {}),
  });
  return [frame(start), frame(end)];
}

export type Scrub = {
  set: (level: number) => void;
  stop: () => void;
};

const NO_SCRUB: Scrub = { set: () => {}, stop: () => {} };

function scrub(element: HTMLElement, keyframes: Keyframe[]): Scrub {
  const animation = element.animate(keyframes, {
    duration: 1000,
    fill: 'both',
  });
  animation.pause();
  return {
    set: (level: number) => {
      animation.currentTime = Math.min(1, Math.max(0, level)) * 1000;
    },
    stop: () => animation.cancel(),
  };
}

export function scrubBackdrop(element: HTMLElement): Scrub {
  if (typeof element.animate !== 'function') return NO_SCRUB;
  const rest = readBackdrop(element);
  return scrub(element, backdropKeyframes(rest, CLEAR, rest));
}

export function scrubShadow(element: HTMLElement): Scrub {
  if (typeof element.animate !== 'function') return NO_SCRUB;
  const shadow = getComputedStyle(element).boxShadow;
  if (!shadow || shadow === 'none') return NO_SCRUB;
  return scrub(element, [{ boxShadow: 'none' }, { boxShadow: shadow }]);
}

export function useBackdropFade(options: {
  visible: boolean;
  enter: Transition;
  exit: Transition;
  onFadedOut?: () => void;
  animated?: boolean;
}): React.RefCallback<HTMLElement> {
  const { visible } = options;
  const elementRef = React.useRef<HTMLElement | null>(null);
  const latestRef = React.useRef(options);
  React.useLayoutEffect(() => {
    latestRef.current = options;
  });
  const runningRef = React.useRef<Animation | null>(null);
  const mountedRef = React.useRef(false);

  React.useLayoutEffect(() => {
    const { animated = true, enter, exit, onFadedOut } = latestRef.current;
    const element = elementRef.current;
    const mounting = !mountedRef.current;
    mountedRef.current = true;
    if (mounting && !visible) return;
    if (!element || !animated || typeof element.animate !== 'function') {
      if (!visible) onFadedOut?.();
      return;
    }
    const current = runningRef.current;
    const midway = current ? readBackdrop(element) : null;
    current?.cancel();
    const rest = readBackdrop(element);
    const { duration, easing } = toCssTiming(visible ? enter : exit);
    const animation = element.animate(
      backdropKeyframes(
        rest,
        midway ?? (visible ? CLEAR : rest),
        visible ? rest : CLEAR,
      ),
      {
        duration,
        easing,
        fill: visible ? 'backwards' : 'forwards',
      },
    );
    runningRef.current = animation;
    animation.finished
      .then(() => {
        if (runningRef.current !== animation) return;
        if (visible) runningRef.current = null;
        else latestRef.current.onFadedOut?.();
      })
      .catch(() => {});
  }, [visible]);

  return React.useCallback((node: HTMLElement | null) => {
    elementRef.current = node;
  }, []);
}

