  React.useEffect(() => value.on('change', setShown), [value]);

  React.useEffect(() => {
    if (reduce) {
      value.jump(target);
      return;
    }
    let controls: AnimationPlaybackControls | undefined;
    const timeout = setTimeout(() => {
      controls = animate(value, target, transitionRef.current);
    }, 0);
    return () => {
      clearTimeout(timeout);
      controls?.stop();
    };
  }, [value, target, reduce]);

  return shown;
}

